/**
 * Represents a UK BNF nomenclature record returned by the OpenPrescribing API:
 * `https://openprescribing.net/api/1.0/bnf_code/?format=json&q={searchTerm}`
 */
export interface BnfMedicationItem {
  /** BNF Code / ID (e.g., "0407010H0", "0301011R0") */
  id: string;
  /** UK BNF / rINN nomenclature name (e.g., "Paracetamol", "Salbutamol") */
  name: string;
  /** Optional entity type returned by OpenPrescribing (e.g., "chemical", "product", "presentation", "section") */
  type?: string;
}

/**
 * Clinical details dynamically generated by the Gemini API for a selected UK medication
 * in Standard Mode.
 */
export interface GeminiClinicalDetails {
  phoneticSpelling: string;
  class: string;
  indications: string[];
  /**
   * Plain-English, pre-hospital summary explaining why a patient is typically prescribed
   * this medication and what an ambulance crew needs to be aware of on scene.
   */
  medicSummary: string;
}

/**
 * Overdose & toxicology details dynamically generated by the Gemini API for a selected UK
 * medication when Toxicity Mode is active.
 */
export interface GeminiToxicityDetails {
  /** Plain-English summary of how the overdose presents clinically and vital sign changes */
  overdoseEffects: string;
  /** Known toxic dose limit, e.g., '>75mg/kg' or specific mg amount */
  toxicThreshold: string;
}

/**
 * Holistic analysis returned by Gemini Vision when scanning an uploaded prescription
 * or repeat medication list, structured as concise bullet points for quick reading.
 */
export interface PrescriptionScanResult {
  /** Distinct UK generic/BNF medication names detected in the image */
  medications: string[];
  /** Standard Mode: Brief bullet points of likely medical conditions / PMH */
  patientConditions: string[];
  /** Standard Mode: Brief pre-hospital on-scene considerations for the crew */
  onSceneBullets: string[];
  /** Toxicity Mode: Brief bullet points on dangerous drug-drug interactions / synergies */
  interactionBullets: string[];
  /** Toxicity Mode: Brief bullet points on key overdose & vital-sign red flags */
  toxRedFlagBullets: string[];
}

export type SpeechSpeed = 1.0 | 0.75;

/**
 * Represents a UK brand-name or fixed-dose combination product expanded into its
 * constituent active generic UK BNF drugs for clear hierarchical display.
 */
export interface BrandProductGroup {
  /** Unique group identifier (e.g. "brand::trimbow") */
  id: string;
  /** Display brand/product name (e.g. "Trimbow") */
  brandName: string;
  /** Optional short clinical/formulation descriptor */
  subtitle?: string;
  /** Separate constituent UK BNF generic drug items */
  constituents: BnfMedicationItem[];
  /** Raw BNF IDs superseded by this brand group so combined cards aren't duplicated */
  supersededBnfIds?: string[];
}

export interface BnfSearchOutcome {
  brandGroups: BrandProductGroup[];
  standaloneItems: BnfMedicationItem[];
}

export interface GeminiBrandResolution {
  isBrandOrCombination: boolean;
  productName: string;
  subtitle?: string;
  constituents: string[];
}
